independent-practice.solution:
def unique_in_order(words):
    seen = set()
    result = []
    for word in words:
        if word not in seen:
            seen.add(word)
            result.append(word)
    return result

def busiest(entries):
    counts = {}
    for name in entries:
        counts[name] = counts.get(name, 0) + 1
    best = None
    best_count = 0
    for name in entries:
        if counts[name] > best_count:
            best = name
            best_count = counts[name]
    return best

def repeat_bookings(bookings):
    taken = set()
    clashes = 0
    for booking in bookings:
        row, seat = booking
        place = (row, seat)
        if place in taken:
            clashes = clashes + 1
        else:
            taken.add(place)
    return clashes

