exam.solution:
def bump_level(record):
    name, level, school = record
    return (name, level + 1, school)

def leaderboard(entries):
    totals = {}
    order = []
    for entry in entries:
        name, points = entry
        if name not in totals:
            totals[name] = 0
            order.append(name)
        totals[name] = totals[name] + points
    result = []
    for name in order:
        result.append([name, totals[name]])
    return result
